-- ============================================================
-- Chatbot de atención al cliente - IFCD0083 Módulo 6
-- Script de base de datos (MySQL 8.x / MariaDB 10.x)
-- Datos 100% FICTICIOS. Los correos usan el dominio example.com.
-- Ejecución:  mysql -u root -p < schema.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS atencion_db
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE atencion_db;

DROP TABLE IF EXISTS atencion_cliente;
DROP TABLE IF EXISTS clientes;

CREATE TABLE clientes (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  nombre      VARCHAR(60)  NOT NULL,
  apellidos   VARCHAR(100) NOT NULL,
  email       VARCHAR(120) NOT NULL,
  telefono    VARCHAR(20)  NULL,
  ciudad      VARCHAR(60)  NULL,
  plan        ENUM('basico','premium','empresa') NOT NULL DEFAULT 'basico',
  fecha_alta  DATE         NOT NULL,
  activo      TINYINT(1)   NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_clientes_email (email)
) ENGINE=InnoDB;

CREATE TABLE atencion_cliente (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  cliente_id  INT UNSIGNED NOT NULL,
  fecha       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  canal       ENUM('web','email','telefono','chatbot') NOT NULL DEFAULT 'web',
  categoria   VARCHAR(40)  NULL,
  consulta    TEXT         NOT NULL,
  respuesta   TEXT         NULL,
  estado      ENUM('resuelta','pendiente','escalada') NOT NULL DEFAULT 'pendiente',
  PRIMARY KEY (id),
  KEY idx_atencion_cliente_fecha (cliente_id, fecha),
  CONSTRAINT fk_atencion_cliente FOREIGN KEY (cliente_id)
    REFERENCES clientes (id) ON DELETE CASCADE
) ENGINE=InnoDB;

