INSERT INTO atencion_cliente (cliente_id, fecha, canal, categoria, consulta, respuesta, estado) VALUES
  (1, '2025-08-22 19:26:00', 'email', 'planes', '¿Qué diferencia hay entre el plan básico y el premium?', 'El plan premium incluye más almacenamiento, soporte prioritario y acceso a informes avanzados. Le hemos enviado un cuadro comparativo detallado a su correo.', 'resuelta'),
  (1, '2025-10-11 19:20:00', 'web', 'cuenta', '¿Puedo activar la verificación en dos pasos?', 'Sí. En Mi Cuenta > Seguridad encontrará la opción de verificación en dos pasos mediante aplicación de autenticación o SMS.', 'resuelta'),
  (2, '2025-12-17 08:30:00', 'web', 'pedidos', 'Quiero cancelar un pedido que acabo de hacer.', 'Si el pedido aún no ha salido del almacén puede cancelarlo desde Mis pedidos > Cancelar. Si ya está en camino, tendrá que rechazarlo en la entrega o solicitar la devolución.', 'resuelta'),
  (3, '2025-06-19 19:44:00', 'telefono', 'facturacion', 'Me han cobrado dos veces la cuota de este mes. ¿Pueden revisarlo?', 'Hemos revisado su cuenta y confirmamos un cargo duplicado. Hemos iniciado la devolución de uno de los cargos; verá el importe reflejado en su cuenta en un plazo de 3 a 5 días hábiles.', 'resuelta'),
  (4, '2025-03-17 11:55:00', 'web', 'pedidos', 'Mi pedido lleva una semana de retraso, ¿dónde está?', 'Hemos localizado su pedido: la transportista registra una incidencia en el centro de reparto. Hemos solicitado la entrega prioritaria y le enviaremos el nuevo código de seguimiento.', 'resuelta'),
  (5, '2025-04-27 10:15:00', 'email', 'soporte_tecnico', 'Las notificaciones han dejado de llegarme.', 'Compruebe en los ajustes del móvil que las notificaciones de la aplicación están permitidas y que el ahorro de batería no la restringe. También revise Mi Cuenta > Notificaciones.', 'resuelta'),
  (6, '2025-04-12 10:34:00', 'chatbot', 'devoluciones', 'Quiero cambiar un producto por otra talla.', 'Puede solicitar el cambio desde Mis pedidos > Solicitar cambio. Enviaremos la nueva talla en cuanto recibamos el producto original.', 'resuelta'),
  (6, '2025-07-03 15:31:00', 'web', 'facturacion', 'No entiendo el importe de mi última factura, es más alto de lo habitual.', 'Su factura incluye el cambio de plan aplicado a mitad de ciclo, que genera un prorrateo. Le hemos enviado el desglose detallado por correo. Si tras revisarlo sigue sin cuadrarle, indíquenoslo y lo escalamos.', 'resuelta'),
  (7, '2025-03-16 17:25:00', 'chatbot', 'cuenta', '¿Cómo puedo cambiar el correo electrónico asociado a mi cuenta?', 'Puede hacerlo en Mi Cuenta > Perfil > Correo electrónico. Recibirá un mensaje de confirmación en la nueva dirección para validar el cambio.', 'resuelta'),
  (7, '2025-04-28 20:35:00', 'chatbot', 'devoluciones', '¿Cuál es el plazo para devolver un producto?', 'Dispone de 14 días naturales desde la recepción para desistir del pedido sin necesidad de justificación, con el producto en su embalaje original.', 'resuelta'),
  (7, '2025-07-04 15:38:00', 'telefono', 'facturacion', '¿Dónde puedo descargar mis facturas anteriores?', 'Puede descargarlas desde Mi Cuenta > Facturación > Historial. Allí encontrará todas las facturas en PDF de los últimos 24 meses.', 'resuelta'),
  (7, '2025-08-28 13:45:00', 'email', 'devoluciones', 'Quiero cambiar un producto por otra talla.', 'Puede solicitar el cambio desde Mis pedidos > Solicitar cambio. Enviaremos la nueva talla en cuanto recibamos el producto original.', 'resuelta'),
  (7, '2025-11-05 15:40:00', 'chatbot', 'facturacion', 'Quiero cambiar los datos fiscales de mi factura, el NIF es incorrecto.', 'Para corregir el NIF necesitamos anular la factura y emitir una nueva. Hemos abierto la solicitud y recibirá la factura rectificada por correo en un máximo de 48 horas.', 'resuelta'),
  (7, '2025-12-24 14:02:00', 'email', 'facturacion', '¿Puedo pagar con transferencia en lugar de tarjeta?', 'Sí, es posible para los planes premium y empresa. Para activarlo debe solicitarlo a un agente, que le facilitará los datos bancarios y las condiciones.', 'escalada'),
  (8, '2025-09-20 15:05:00', 'email', 'pedidos', '¿Cómo puedo cambiar la dirección de entrega de mi pedido?', 'Mientras el pedido esté en preparación puede modificar la dirección desde Mis pedidos > Editar entrega. Una vez enviado ya no es posible; contacte con la transportista.', 'resuelta'),
  (9, '2025-02-25 09:22:00', 'email', 'devoluciones', 'Han pasado 10 días desde mi devolución y no he recibido el reembolso.', 'Tras recibir y revisar el producto, el reembolso tarda hasta 14 días en reflejarse según su banco. Hemos comprobado que su devolución ya fue procesada; si en 5 días no lo ve, escríbanos de nuevo.', 'pendiente'),
  (10, '2025-01-15 17:18:00', 'email', 'soporte_tecnico', 'La sincronización entre mi ordenador y el móvil no funciona.', 'Verifique que ambos dispositivos usan la misma cuenta y tienen conexión. Hemos forzado una resincronización desde nuestro lado; puede tardar unos minutos en reflejarse.', 'resuelta'),
  (10, '2025-04-21 14:12:00', 'chatbot', 'facturacion', '¿Dónde puedo descargar mis facturas anteriores?', 'Puede descargarlas desde Mi Cuenta > Facturación > Historial. Allí encontrará todas las facturas en PDF de los últimos 24 meses.', 'resuelta'),
  (11, '2025-03-21 18:50:00', 'telefono', 'facturacion', '¿Puedo pagar con transferencia en lugar de tarjeta?', 'Sí, es posible para los planes premium y empresa. Para activarlo debe solicitarlo a un agente, que le facilitará los datos bancarios y las condiciones.', 'escalada'),
  (11, '2025-04-12 08:34:00', 'web', 'soporte_tecnico', 'Me aparece un error al subir archivos de más de 50 MB.', 'El límite actual de subida es de 100 MB en planes premium y 25 MB en el plan básico. Si necesita más capacidad, puede ampliar el plan o dividir el archivo.', 'escalada'),
  (11, '2025-05-09 12:07:00', 'email', 'pedidos', 'El paquete llegó dañado, ¿qué hago?', 'Por favor, haga fotos del paquete y del producto y envíelas respondiendo al correo de confirmación. Con esa documentación tramitaremos el reemplazo o el reembolso.', 'pendiente'),
  (11, '2025-07-05 17:21:00', 'chatbot', 'facturacion', '¿Dónde puedo descargar mis facturas anteriores?', 'Puede descargarlas desde Mi Cuenta > Facturación > Historial. Allí encontrará todas las facturas en PDF de los últimos 24 meses.', 'resuelta'),
  (12, '2025-07-01 15:33:00', 'chatbot', 'pedidos', 'Me ha llegado un producto distinto al que pedí.', 'Lamentamos el error. Hemos generado una etiqueta de devolución gratuita que recibirá por correo y enviaremos el producto correcto en cuanto recojan el paquete.', 'resuelta'),
  (13, '2025-05-05 12:40:00', 'email', 'facturacion', 'No entiendo el importe de mi última factura, es más alto de lo habitual.', 'Su factura incluye el cambio de plan aplicado a mitad de ciclo, que genera un prorrateo. Le hemos enviado el desglose detallado por correo. Si tras revisarlo sigue sin cuadrarle, indíquenoslo y lo escalamos.', 'resuelta'),
  (13, '2025-08-05 09:50:00', 'email', 'pedidos', 'Me ha llegado un producto distinto al que pedí.', 'Lamentamos el error. Hemos generado una etiqueta de devolución gratuita que recibirá por correo y enviaremos el producto correcto en cuanto recojan el paquete.', 'resuelta'),
  (14, '2025-02-08 10:03:00', 'telefono', 'cuenta', 'No recuerdo mi contraseña y no me llega el correo de recuperación.', 'Revise la carpeta de spam. Si no lo encuentra, hemos reenviado el enlace de recuperación a su correo registrado; tiene validez de 24 horas.', 'resuelta'),
  (14, '2025-05-18 16:24:00', 'telefono', 'planes', '¿Puedo bajar de plan sin perder mis datos?', 'Sí, puede cambiar a un plan inferior en cualquier momento. Sus datos se conservan siempre que no superen el límite de almacenamiento del nuevo plan.', 'resuelta'),
  (14, '2025-06-15 14:38:00', 'web', 'planes', 'Quiero subir mi plan a premium, ¿cómo se aplica el cobro?', 'El cambio es inmediato y se cobra la diferencia prorrateada por los días restantes del ciclo. Puede hacerlo en Mi Cuenta > Plan.', 'resuelta'),
  (14, '2025-12-25 14:14:00', 'telefono', 'devoluciones', '¿Quién paga los gastos de envío de una devolución?', 'Si la devolución es por error nuestro o producto defectuoso, los gastos son gratuitos. En el resto de casos corren por cuenta del cliente, salvo promociones específicas.', 'resuelta'),
  (15, '2025-05-22 09:29:00', 'chatbot', 'devoluciones', '¿Quién paga los gastos de envío de una devolución?', 'Si la devolución es por error nuestro o producto defectuoso, los gastos son gratuitos. En el resto de casos corren por cuenta del cliente, salvo promociones específicas.', 'resuelta'),
  (16, '2025-07-12 19:55:00', 'web', 'planes', '¿Puedo bajar de plan sin perder mis datos?', 'Sí, puede cambiar a un plan inferior en cualquier momento. Sus datos se conservan siempre que no superen el límite de almacenamiento del nuevo plan.', 'resuelta'),
  (16, '2025-09-27 16:06:00', 'telefono', 'pedidos', 'El paquete llegó dañado, ¿qué hago?', 'Por favor, haga fotos del paquete y del producto y envíelas respondiendo al correo de confirmación. Con esa documentación tramitaremos el reemplazo o el reembolso.', 'pendiente'),
  (17, '2025-02-19 08:04:00', 'chatbot', 'pedidos', 'Mi pedido lleva una semana de retraso, ¿dónde está?', 'Hemos localizado su pedido: la transportista registra una incidencia en el centro de reparto. Hemos solicitado la entrega prioritaria y le enviaremos el nuevo código de seguimiento.', 'resuelta'),
  (17, '2025-06-14 15:02:00', 'web', 'soporte_tecnico', 'La aplicación se cierra sola al abrirla en el móvil.', 'Pruebe a actualizar la aplicación a la última versión y reiniciar el dispositivo. Si persiste, desinstale y vuelva a instalar; sus datos están en la nube y no se perderán.', 'resuelta'),
  (17, '2025-12-08 13:59:00', 'web', 'soporte_tecnico', 'La aplicación se cierra sola al abrirla en el móvil.', 'Pruebe a actualizar la aplicación a la última versión y reiniciar el dispositivo. Si persiste, desinstale y vuelva a instalar; sus datos están en la nube y no se perderán.', 'resuelta'),
  (18, '2025-07-26 18:51:00', 'chatbot', 'planes', '¿Qué diferencia hay entre el plan básico y el premium?', 'El plan premium incluye más almacenamiento, soporte prioritario y acceso a informes avanzados. Le hemos enviado un cuadro comparativo detallado a su correo.', 'resuelta'),
  (19, '2025-02-20 16:01:00', 'email', 'pedidos', 'Quiero cancelar un pedido que acabo de hacer.', 'Si el pedido aún no ha salido del almacén puede cancelarlo desde Mis pedidos > Cancelar. Si ya está en camino, tendrá que rechazarlo en la entrega o solicitar la devolución.', 'resuelta'),
  (19, '2025-04-23 20:46:00', 'chatbot', 'soporte_tecnico', 'La sincronización entre mi ordenador y el móvil no funciona.', 'Verifique que ambos dispositivos usan la misma cuenta y tienen conexión. Hemos forzado una resincronización desde nuestro lado; puede tardar unos minutos en reflejarse.', 'resuelta'),
  (19, '2025-07-08 09:44:00', 'web', 'cuenta', 'No recuerdo mi contraseña y no me llega el correo de recuperación.', 'Revise la carpeta de spam. Si no lo encuentra, hemos reenviado el enlace de recuperación a su correo registrado; tiene validez de 24 horas.', 'resuelta'),
  (19, '2025-09-01 10:57:00', 'telefono', 'planes', 'Necesito añadir usuarios adicionales a mi plan de empresa.', 'Puede añadir usuarios desde el panel de administración, en Equipo > Invitar. Cada usuario adicional se factura según la tarifa de su plan.', 'resuelta'),
  (20, '2025-02-13 09:10:00', 'telefono', 'cuenta', 'No recuerdo mi contraseña y no me llega el correo de recuperación.', 'Revise la carpeta de spam. Si no lo encuentra, hemos reenviado el enlace de recuperación a su correo registrado; tiene validez de 24 horas.', 'resuelta'),
  (20, '2025-11-19 10:28:00', 'chatbot', 'cuenta', 'Mi cuenta aparece bloqueada tras varios intentos fallidos.', 'Por seguridad, la cuenta se bloquea 30 minutos tras 5 intentos fallidos. Pasado ese tiempo podrá acceder de nuevo o restablecer la contraseña desde la pantalla de acceso.', 'resuelta'),
  (21, '2025-07-09 15:49:00', 'chatbot', 'soporte_tecnico', 'La aplicación se cierra sola al abrirla en el móvil.', 'Pruebe a actualizar la aplicación a la última versión y reiniciar el dispositivo. Si persiste, desinstale y vuelva a instalar; sus datos están en la nube y no se perderán.', 'resuelta'),
  (21, '2025-12-03 20:38:00', 'web', 'facturacion', 'Me han cobrado dos veces la cuota de este mes. ¿Pueden revisarlo?', 'Hemos revisado su cuenta y confirmamos un cargo duplicado. Hemos iniciado la devolución de uno de los cargos; verá el importe reflejado en su cuenta en un plazo de 3 a 5 días hábiles.', 'resuelta'),
